    }
  }

  protected reasonChanged(id: number, reason: string): void {
    this.clearRowError(id);
    this.rejectReasons.update((rs) => ({ ...rs, [id]: reason }));
  }

  /** Reject a PENDING claim with the reason typed for it; it goes back to OPEN. */
