560	    }
561	  }
562	
563	  protected voidReasonChanged(id: number, reason: string): void {
564	    this.clearRowError(id);
565	    this.voidChoices.update((rs) => ({ ...rs, [id]: reason }));
566	  }
567	
568	  /** Void a claim, with the reason chosen for it while the sheet has a list of void reasons; a
569	   *  void without one then is refused with an error on the claim. */
570	  protected async voidClaim(c: Claim): Promise<void> {
571	    this.clearRowError(c.id);
572	    const sheetId = this.session.sheetId();
573	    if (!sheetId) return;
574	    const reasons = this.session.voidReasons();
575	    const chosen = this.voidChoices()[c.id] ?? '';
576	    const reason = reasons.includes(chosen) ? chosen : null;
577	    if (reasons.length > 0 && reason === null) {
578	      this.rowErrors.update((errs) => ({ ...errs, [c.id]: VOID_REASON_NEEDED }));
579	      return;
580	    }
581	    try {
582	      const claim = await this.api.voidClaim(sheetId, c.id, reason);
583	      this.voidChoices.update(({ [c.id]: _, ...rest }) => rest);
584	      if (this.session.sheetId() === sheetId) this.saved.emit(claim);
585	    } catch (e) {
586	      this.rowErrors.update((errs) => ({ ...errs, [c.id]: voidError(e, this.isOpenerOrEditor(c)) }));
587	    }
588	  }
589	
590	  /** Open, settle, approve, re-settle or void a claim; a move its status does not allow shows an error on the claim. */
591	  protected async changeStatus(c: Claim, action: ClaimAction): Promise<void> {
592	    this.clearRowError(c.id);
593	    const sheetId = this.session.sheetId();
594	    if (!sheetId) return;
595	    try {
596	      const claim = await this.api.changeStatus(sheetId, c.id, action);
597	      if (this.session.sheetId() === sheetId) this.saved.emit(claim);
598	    } catch (e) {
599	      const err = action === 'resettle' ? resettleError(e) : statusError(e, this.isOpenerOrEditor(c));
600	      this.rowErrors.update((errs) => ({ ...errs, [c.id]: err }));
601	    }
602	  }
603	
604	  /** Whether the user opened or last edited the claim, and so may not settle or approve it. */
605	  private isOpenerOrEditor(c: Claim): boolean {
606	    const user = this.session.user();
607	    return c.openedBy === user || c.editedBy === user;
608	  }
609	
610	  protected splitAmountChanged(id: number, amount: string): void {
611	    this.clearRowError(id);
612	    this.splitAmounts.update((as) => ({ ...as, [id]: amount }));
613	  }
614	
615	  /** Split the amount typed for it off an OPEN claim; the original keeps the rest and the new
616	   *  claim is listed first. A refusal shows an error on the claim. */
617	  protected async split(c: Claim): Promise<void> {
618	    this.clearRowError(c.id);
619	    const sheetId = this.session.sheetId();
620	    if (!sheetId) return;
621	    const amount = (this.splitAmounts()[c.id] ?? '').trim();
622	    if (!AMOUNT_PATTERN.test(amount)) {
623	      this.rowErrors.update((errs) => ({ ...errs, [c.id]: 'Enter an amount with up to two decimals to split off.' }));
624	      return;
625	    }
626	    try {
627	      const { original, split } = await this.api.split(sheetId, c.id, amount);
628	      this.splitAmounts.update(({ [c.id]: _, ...rest }) => rest);
629	      if (this.session.sheetId() === sheetId) {
630	        this.saved.emit(original);
631	        this.saved.emit(split);
632	      }
633	    } catch (e) {
634	      this.rowErrors.update((errs) => ({ ...errs, [c.id]: splitError(e) }));
635	    }
636	  }
637	
638	  protected inlineAmountChanged(id: number, amount: string): void {
639	    this.clearRowError(id);
640	    this.inlineAmounts.update((as) => ({ ...as, [id]: amount }));
641	  }
642	
643	  /** Change a DRAFT claim's amount to the one typed in its row, keeping its date, note and what
644	   *  it corrects, by the claim form's rules; a refusal shows an error on the claim. */
645	  protected async saveInline(c: Claim): Promise<void> {
646	    this.clearRowError(c.id);
647	    const sheetId = this.session.sheetId();
648	    if (!sheetId) return;
649	    const amount = (this.inlineAmounts()[c.id] ?? '').trim();
650	    if (!CLAIM_AMOUNT_PATTERN.test(amount)) {
651	      this.rowErrors.update((errs) => ({ ...errs, [c.id]: 'Enter an amount with up to two decimals.' }));
652	      return;
653	    }
654	    try {
655	      const claim = await this.api.update(sheetId, c.id, { amount, date: c.date, note: c.note, corrects: c.corrects, ref: c.ref, tags: c.tags });
656	      if (this.session.sheetId() === sheetId) this.saved.emit(claim);
657	    } catch (e) {
658	      this.rowErrors.update((errs) => ({ ...errs, [c.id]: claimError(e, amount.startsWith('-')) }));
659	    }
660	  }
661	
662	  /** Move a claim to another person; a refusal shows an error on the claim. */
663	  protected async reassign(c: Claim, personId: string): Promise<void> {
664	    this.clearRowError(c.id);
665	    const sheetId = this.session.sheetId();
666	    if (!sheetId) return;
667	    if (!personId) {
668	      this.rowErrors.update((errs) => ({ ...errs, [c.id]: 'Choose a person to reassign the claim to.' }));
669	      return;
670	    }
671	    try {
672	      const claim = await this.api.reassign(sheetId, c.id, Number(personId));
673	      if (this.session.sheetId() === sheetId) this.saved.emit(claim);
674	    } catch (e) {
675	      this.rowErrors.update((errs) => ({ ...errs, [c.id]: reassignError(e) }));
676	    }
677	  }
678	
679	  protected clearRowError(id: number): void {
680	    this.rowErrors.update(({ [id]: _, ...rest }) => rest);
681	  }
682	
683	  protected reset(): void {
684	    this.editingId.set(null);
685	    this.locking = null;
686	    this.form.reset({ amount: '', date: '', note: '', corrects: '', ref: '', tags: '' });
687	    this.error.set(null);
688	  }
689	}
