301	    /** Settle the claims (in the order given) as {@link #changeStatus} does, all or nothing, as the
302	     *  sheet's next batch: each claim carries the batch's number, a claim sent to PENDING counts in
303	     *  it, and BATCH_SETTLED follows the claims' own records with the batch's count and the total of
304	     *  the frozen figures of those SETTLED. Any refusal refuses the whole batch, leaving every claim
305	     *  as it was and recording nothing. */
306	    @Transactional
307	    public void settleBatch(String sheetId, String user, List<Long> ids) {
308	        if (ids.isEmpty()) {
309	            return;
310	        }
311	        int number = claims.findLastBatch(sheetId) + 1;
312	        BigDecimal total = BigDecimal.ZERO.setScale(2);
313	        for (long id : ids) {
314	            Claim claim = changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null);
315	            claim.setBatch(number);
316	            claims.save(claim);
317	            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
318	                total = total.add(claim.getSettledDue());
319	            }
320	        }
321	        claims.flush();
322	        audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + number
323	                + " count=" + ids.size() + " total=" + total.setScale(2).toPlainString());
324	    }
