334	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus to, String voidReason) {
335	        Claim claim = claims.findForUpdate(id, sheetId)
336	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
337	        refuseIfClosed(sheetId, claim.getDueBy());
338	        switch (to) {
339	            case OPEN -> settings.refuseUnlessAllowed(sheetId, user, Permission.OPEN);
340	            case SETTLED -> settings.refuseUnlessAllowed(sheetId, user, Permission.SETTLE);
341	            case VOID -> settings.refuseUnlessAllowed(sheetId, user, Permission.VOID);
342	            default -> {
343	            }
344	        }
345	        if (to == ClaimStatus.PENDING || (to == ClaimStatus.SETTLED && claim.getStatus() == ClaimStatus.PENDING)
346	                || !claim.getStatus().canMoveTo(to)) {
347	            throw new ResponseStatusException(HttpStatus.CONFLICT,
348	                    "A " + claim.getStatus() + " claim cannot become " + to);
349	        }
350	        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
351	            refuseUnlessVoidableSettled(sheetId, user, claim);
352	        }
353	        if (to == ClaimStatus.VOID) {
354	            refuseUnlessListedReason(sheetId, voidReason);
355	        }
356	        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
357	            throw new ResponseStatusException(HttpStatus.CONFLICT,
358	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
359	        }
360	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
361	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
362	                    "The user who opened a claim cannot settle it");
363	        }
364	        if (to == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
365	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
366	                    "The user who last edited a claim cannot settle it");
367	        }
368	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
369	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
370	        if (to == ClaimStatus.OPEN) {
371	            refuseIfNoteless(claim, shownDueOf(claim, person));
372	        }
373	        // a claim bound by a statement settles at its bound figure, its late charge frozen in
374	        BigDecimal settling = to == ClaimStatus.SETTLED ? shownDueOf(claim, person) : null;
375	        if (to == ClaimStatus.SETTLED) {
376	            // before the clerk limit: a claim needing a proof never goes to PENDING
377	            refuseIfUnproven(claim, person, settling);
378	        }
379	        if (to == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, settling)) {
380	            // above the clerk limit: a steward approves or rejects it
381	            to = ClaimStatus.PENDING;
382	        }
383	        RollupService.Snapshot before = rollup.snapshot(sheetId);
384	        // a voided claim keeps its number (never reused), and the VOIDED record carries it
385	        String number = claim.getNumber();
386	        // a voided SETTLED claim keeps its frozen figure, which leaves every total
387	        boolean reversing = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
388	        BigDecimal reversed = claim.getSettledDue();
389	        claim.setStatus(to);
390	        if (to == ClaimStatus.OPEN) {
391	            number = nextNumber(sheetId, claim.getDueBy());
392	            claim.setNumber(number);
393	            claim.setOpenedBy(user);
394	        } else if (to == ClaimStatus.SETTLED) {
395	            claim.setSettledDue(settling);
396	        } else if (to == ClaimStatus.VOID) {
397	            claim.setVoidReason(voidReason);
398	        }
399	        claims.flush();
400	        logStatus(user, person, claim);
401	        String event = switch (to) {
402	            case OPEN -> "CLAIM_OPENED";
403	            case PENDING -> "CLAIM_PENDING";
404	            case SETTLED -> "CLAIM_SETTLED";
405	            case VOID -> "CLAIM_VOIDED";
406	            case DRAFT -> throw new IllegalArgumentException("A claim cannot return to DRAFT");
407	        };
408	        if (to == ClaimStatus.SETTLED) {
409	            record(event, user, person, claim, number, " due=" + dueText(claim.getSettledDue()));
410	            notifyWatchers(user, person, number);
411	        } else if (to == ClaimStatus.VOID) {
412	            record(event, user, person, claim, number, (reversing ? " reversed=" + dueText(reversed) : "")
413	                    + (voidReason != null ? " reason=" + voidReason : ""));
414	        } else {
415	            record(event, user, person, claim, number);
416	        }
417	        rollup.recordChanges(sheetId, user, before);
418	        return claim;
419	    }
