430	    /** Refuse voiding a SETTLED claim (403) by anyone but a steward, and (409) once the sheet's
431	     *  today is more than {@link ClaimStatus#SETTLED_VOID_DAYS} days after its settlement (the
432	     *  first SETTLED line of its status log). */
433	    private void refuseUnlessVoidableSettled(String sheetId, String user, Claim claim) {
434	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
435	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward voids a SETTLED claim");
436	        }
437	        LocalDate settledOn = log.findByClaimIdOrderByIdAsc(claim.getId()).stream()
438	                .filter(line -> line.getStatus() == ClaimStatus.SETTLED)
439	                .map(ClaimLog::getOn)
440	                .findFirst()
441	                .orElse(null);
442	        LocalDate today = sheets.today(sheetId);
443	        if (settledOn == null || today.isAfter(settledOn.plusDays(ClaimStatus.SETTLED_VOID_DAYS))) {
444	            throw new ResponseStatusException(HttpStatus.CONFLICT,
445	                    "A SETTLED claim is voided only within " + ClaimStatus.SETTLED_VOID_DAYS + " days of its settlement");
446	        }
447	    }
