577	    /** Refuse (422) settling or approving a claim at a due (null: n/a) above the proof threshold in
578	     *  force on its date (its person's grade's then when one is set, else the sheet's) while it has
579	     *  no proof. */
580	    private void refuseIfUnproven(Claim claim, Person person, BigDecimal due) {
581	        if (claim.getProofs() > 0 || due == null) {
582	            return;
583	        }
584	        BigDecimal threshold = sheets.proofThresholdFor(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
585	        if (threshold != null && due.compareTo(threshold) > 0) {
586	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
587	                    "A claim whose due is above the proof threshold needs a proof first");
588	        }
589	    }
