591	    /** Refuse (422) opening a claim at a due (null: n/a) above the note threshold in force on its
592	     *  date while its note is empty. */
593	    private void refuseIfNoteless(Claim claim, BigDecimal due) {
594	        if (due == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
595	            return;
596	        }
597	        BigDecimal threshold = sheets.noteThresholdOn(claim.getSheetId(), claim.getDate());
598	        if (threshold != null && due.compareTo(threshold) > 0) {
599	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
600	                    "A claim whose due is above the note threshold needs a note first");
601	        }
602	    }
