614	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim");
615	        }
616	        if (claim.getStatus() != ClaimStatus.SETTLED) {
617	            throw new ResponseStatusException(HttpStatus.CONFLICT,
618	                    "Only a SETTLED claim is re-settled, not a " + claim.getStatus() + " one");
619	        }
620	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
621	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
