664	    /** Reassign a claim as {@link #reassign(String, String, long, long)} does; when {@code toSame}
665	     *  a claim already the person's is moved too (listed as their newest), as a bulk reassign does. */
666	    @Transactional
667	    public Claim reassign(String sheetId, String user, long id, long toPersonId, boolean toSame) {
668	        Claim claim = claims.findForUpdate(id, sheetId)
669	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
670	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
671	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
